    data class Custom(
        val `name`: kotlin.String) : RouteKind()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeRouteKind : FfiConverterRustBuffer<RouteKind>{
    override fun read(buf: ByteBuffer): RouteKind {
        return when(buf.getInt()) {
            1 -> RouteKind.Direct
            2 -> RouteKind.Relay
            3 -> RouteKind.Tor
            4 -> RouteKind.Custom(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RouteKind) = when(value) {
        is RouteKind.Direct -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is RouteKind.Relay -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is RouteKind.Tor -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is RouteKind.Custom -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
    }

    override fun write(value: RouteKind, buf: ByteBuffer) {
        when(value) {
            is RouteKind.Direct -> {
                buf.putInt(1)
                Unit
            }
            is RouteKind.Relay -> {
                buf.putInt(2)
                Unit
            }
            is RouteKind.Tor -> {
                buf.putInt(3)
                Unit
            }
            is RouteKind.Custom -> {
                buf.putInt(4)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Core's workspace phase. It is exhaustive in core, so UniFFI exports it
 * as a remote type with no mirror.
 */

enum class WorkspacePhase {
    
    EMPTY,
    CREATING,
    JOINING,
    SYNCHRONIZING,
    ACTIVE,
    RECOVERING,
    LEAVING,
    RESETTING,
    REMOVED,
    FAILED;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeWorkspacePhase: FfiConverterRustBuffer<WorkspacePhase> {
    override fun read(buf: ByteBuffer) = try {
        WorkspacePhase.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: WorkspacePhase) = 4UL

    override fun write(value: WorkspacePhase, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






